DECLARE expected_delta bigint; packs jsonb := $pack$[{"codigo":"S22AF-C01","legacy_id":161,"coberturas":[{"legacy_id":161,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Cobertura conjunta de CLIENT_HOME y CLIENT_PAYMENTS mediante gemelos de condición y contrato fuente idénticos."}],"paquete":{"tipo":"NUEVA","codigo":"S22AF-C01","clave":"s22af_legacy_161","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Redondeo de cuotas hacia arriba","descripcion":"BLOQUEAR incumplimiento: Todos los montos de cuotas mensuales se redondean hacia arriba (ceiling) al entero más cercano. El copy usa \"Total estimado\" (no \"Total del plan\") para comunicar que el monto puede variar según la fecha de débito elegida. Referencias literales del contrato fuente: {\"metodo\":\"ceiling\",\"ejemplo\":\"683.33 → 684\",\"aplica_a\":\"monto_cuota_mensual\",\"precision\":\"entero_sin_decimales\",\"copy_total\":\"Total estimado\",\"copy_prohibido\":\"Total del plan\"}.  Binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/161","solicitante":"Cristhian / Claude S22-AF"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"af_cuota"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"af_ceiling_bad"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"af_copy_bad"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"af_cuota":true,"af_ceiling_bad":false,"af_copy_bad":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"af_cuota":true,"af_ceiling_bad":true,"af_copy_bad":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_cuota":true,"af_ceiling_bad":false,"af_copy_bad":true},"esperado":true}]},"relacionadas":["S22AF-C05"],"hash_paquete":"0edd1571b7c25f3648f08897dc002b9bc6b390b7a48302ef3e0f1e13d3528336","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AF-C02","legacy_id":192,"coberturas":[{"legacy_id":192,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Cobertura conjunta de CLIENT_HOME y CLIENT_PAYMENTS mediante gemelos de condición y contrato fuente idénticos."},{"legacy_id":233,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Fallback visual contractual sin_oferta cubierto conjuntamente con S22AF-C03 y gemelo CLIENT_PAYMENTS."}],"paquete":{"tipo":"NUEVA","codigo":"S22AF-C02","clave":"s22af_legacy_192","familia":"LOADING_EMPTY_ERROR_STATES","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Error en cruce de DNI para home_variant","descripcion":"BLOQUEAR incumplimiento: Si el cruce de DNI falla o supera el timeout de 5s: mostrar skeleton de carga con \"Estamos buscando tus opciones...\" hasta 5s. Si falla, mostrar home_variant=sin_oferta con mensaje \"En este momento no pudimos cargar tus opciones. Intenta de nuevo más tarde.\" Referencias literales del contrato fuente: {\"fallback\":\"home_variant_sin_oferta\",\"timeout_s\":5,\"mensaje_fallback\":\"En este momento no pudimos cargar tus opciones. Intenta de nuevo más tarde.\"}. Tiempo: public.lf_global_config CLIENT.DNI_CROSS_TIMEOUT_SECONDS. Binding runtime pendiente. Contrato relacionado REG_B2B_003 (233): BLOQUEAR incumplimiento: El aliado debe responder el cruce de DNI en máximo 5 segundos. Si supera ese tiempo, LF muestra home_variant=sin_oferta como fallback. El SLA es un requisito contractual con el aliado. Referencias literales del contrato fuente: {\"tipo\":\"requisito_contractual\",\"sla_cruce_dni_s\":5,\"fallback_si_supera\":\"sin_oferta\"}. Tiempo: public.lf_global_config CLIENT.DNI_CROSS_TIMEOUT_SECONDS. Binding runtime pendiente. En el cliente se exige fallback sin_oferta al superar el parámetro compartido; el SLA contractual se controla en S22AF-C03.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/192","solicitante":"Cristhian / Claude S22-AF"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"af_cross"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"af_skeleton_bad"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"af_failed"},"der":{"lit":true}},"der":{"op":">","izq":{"hecho":"af_dni_seconds"},"der":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS"}}},"der":{"op":"=","izq":{"hecho":"af_fallback_bad"},"der":{"lit":true}}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"af_cross":true,"af_failed":false,"af_skeleton_bad":false,"af_fallback_bad":false,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":0}},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"af_cross":true,"af_failed":true,"af_skeleton_bad":false,"af_fallback_bad":true,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":-1}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_cross":true,"af_failed":false,"af_skeleton_bad":false,"af_fallback_bad":true,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":1}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_cross":true,"af_failed":false,"af_skeleton_bad":true,"af_fallback_bad":false,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":-1}},"esperado":true}]},"relacionadas":["S22AF-C06","S22AF-C03"],"hash_paquete":"afd95bd2a3b1739628426c497a3a465b0c84a447eff61e47b2683d7284893f00","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AF-C03","legacy_id":233,"coberturas":[{"legacy_id":233,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"SLA contractual B2B complementado por fallback literal en S22AF-C02 y S22AF-C06."}],"paquete":{"tipo":"NUEVA","codigo":"S22AF-C03","clave":"s22af_legacy_233","familia":"B2B_PARTNERS","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"B2B","modo":"HEREDA","dueno":"PRODUCTO","titulo":"SLA de respuesta del aliado para cruce de DNI","descripcion":"BLOQUEAR incumplimiento: El aliado debe responder el cruce de DNI en máximo 5 segundos. Si supera ese tiempo, LF muestra home_variant=sin_oferta como fallback. El SLA es un requisito contractual con el aliado. Referencias literales del contrato fuente: {\"tipo\":\"requisito_contractual\",\"sla_cruce_dni_s\":5,\"fallback_si_supera\":\"sin_oferta\"}. Tiempo: public.lf_global_config CLIENT.DNI_CROSS_TIMEOUT_SECONDS. Binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/233","solicitante":"Cristhian / Claude S22-AF"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"af_ally_cross"},"der":{"lit":true}},"der":{"op":">","izq":{"hecho":"af_dni_seconds"},"der":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS"}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"af_ally_cross":true,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":0}},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"af_ally_cross":true,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":1}},"esperado":true}]},"relacionadas":["S22AF-C02","S22AF-C06"],"hash_paquete":"c95784efe6bd95ddaf7ad53aebcdc90d5e8a390fc5adaa4a5db3e2fb613bb0ee","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AF-C04","legacy_id":204,"coberturas":[{"legacy_id":204,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Cobertura conjunta de CLIENT_HOME y CLIENT_PAYMENTS mediante gemelos de condición y contrato fuente idénticos."}],"paquete":{"tipo":"NUEVA","codigo":"S22AF-C04","clave":"s22af_legacy_204","familia":"UI_MESSAGES","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Estados del countdown de vencimiento","descripcion":"BLOQUEAR incumplimiento: El countdown de vencimiento tiene 3 estados visuales según tiempo restante: (1) normal (>24h): texto verde, sin urgencia. (2) alerta (6h-24h): texto naranja, icono de reloj animado. (3) crítico (<6h): texto rojo, fondo rojo muy suave, pulso sutil. Referencias literales del contrato fuente: {\"estados\":{\"alerta\":{\"color\":\"naranja\",\"icono\":\"reloj_animado\",\"umbral\":\"6h-24h\"},\"normal\":{\"color\":\"verde\",\"umbral\":\">24h\"},\"critico\":{\"color\":\"rojo\",\"fondo\":\"rojo_suave\",\"umbral\":\"<6h\",\"animacion\":\"pulso\"}}}. Umbrales: public.lf_global_config CLIENT.COUNTDOWN_NORMAL_HOURS y CLIENT.COUNTDOWN_CRITICAL_HOURS. Binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/204","solicitante":"Cristhian / Claude S22-AF"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"af_countdown"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"y","izq":{"op":">","izq":{"hecho":"af_hours_normal"},"der":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS"}},"der":{"op":"=","izq":{"hecho":"af_normal_bad"},"der":{"lit":true}}},"der":{"op":"y","izq":{"op":"y","izq":{"op":">=","izq":{"hecho":"af_hours_critical"},"der":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS"}},"der":{"op":"<=","izq":{"hecho":"af_hours_normal"},"der":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS"}}},"der":{"op":"=","izq":{"hecho":"af_alert_bad"},"der":{"lit":true}}}},"der":{"op":"y","izq":{"op":"<","izq":{"hecho":"af_hours_critical"},"der":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS"}},"der":{"op":"=","izq":{"hecho":"af_critical_bad"},"der":{"lit":true}}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":true,"af_alert_bad":false,"af_critical_bad":false,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":1},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":19}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":false,"af_alert_bad":true,"af_critical_bad":false,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":0},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":18}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":false,"af_alert_bad":true,"af_critical_bad":false,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":-18},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":0}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":false,"af_alert_bad":false,"af_critical_bad":true,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":-19},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":-1}},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":true,"af_alert_bad":false,"af_critical_bad":true,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":0},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":18}},"esperado":false}]},"relacionadas":["S22AF-C07"],"hash_paquete":"27972bab11cbc20891d546dd647791921533041be2e3641a2af40995803e0407","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AF-C05","legacy_id":161,"coberturas":[{"legacy_id":161,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Cobertura conjunta de CLIENT_HOME y CLIENT_PAYMENTS mediante gemelos de condició