_id":192,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Cobertura conjunta de CLIENT_HOME y CLIENT_PAYMENTS mediante gemelos de condición y contrato fuente idénticos."},{"legacy_id":233,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Fallback visual contractual sin_oferta cubierto conjuntamente con S22AF-C03 y gemelo CLIENT_PAYMENTS."}],"paquete":{"tipo":"NUEVA","codigo":"S22AF-C06","clave":"s22af_legacy_192_payments","familia":"LOADING_EMPTY_ERROR_STATES","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Error en cruce de DNI para home_variant","descripcion":"BLOQUEAR incumplimiento: Si el cruce de DNI falla o supera el timeout de 5s: mostrar skeleton de carga con \"Estamos buscando tus opciones...\" hasta 5s. Si falla, mostrar home_variant=sin_oferta con mensaje \"En este momento no pudimos cargar tus opciones. Intenta de nuevo más tarde.\" Referencias literales del contrato fuente: {\"fallback\":\"home_variant_sin_oferta\",\"timeout_s\":5,\"mensaje_fallback\":\"En este momento no pudimos cargar tus opciones. Intenta de nuevo más tarde.\"}. Tiempo: public.lf_global_config CLIENT.DNI_CROSS_TIMEOUT_SECONDS. Binding runtime pendiente. Contrato relacionado REG_B2B_003 (233): BLOQUEAR incumplimiento: El aliado debe responder el cruce de DNI en máximo 5 segundos. Si supera ese tiempo, LF muestra home_variant=sin_oferta como fallback. El SLA es un requisito contractual con el aliado. Referencias literales del contrato fuente: {\"tipo\":\"requisito_contractual\",\"sla_cruce_dni_s\":5,\"fallback_si_supera\":\"sin_oferta\"}. Tiempo: public.lf_global_config CLIENT.DNI_CROSS_TIMEOUT_SECONDS. Binding runtime pendiente. En el cliente se exige fallback sin_oferta al superar el parámetro compartido; el SLA contractual se controla en S22AF-C03.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/192","solicitante":"Cristhian / Claude S22-AF"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"af_cross"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"af_skeleton_bad"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"af_failed"},"der":{"lit":true}},"der":{"op":">","izq":{"hecho":"af_dni_seconds"},"der":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS"}}},"der":{"op":"=","izq":{"hecho":"af_fallback_bad"},"der":{"lit":true}}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"af_cross":true,"af_failed":false,"af_skeleton_bad":false,"af_fallback_bad":false,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":0}},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"af_cross":true,"af_failed":true,"af_skeleton_bad":false,"af_fallback_bad":true,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":-1}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_cross":true,"af_failed":false,"af_skeleton_bad":false,"af_fallback_bad":true,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":1}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_cross":true,"af_failed":false,"af_skeleton_bad":true,"af_fallback_bad":false,"af_dni_seconds":{"param":"CLIENT.DNI_CROSS_TIMEOUT_SECONDS","mas":-1}},"esperado":true}]},"relacionadas":["S22AF-C02","S22AF-C03"],"hash_paquete":"f1de05e5b26f20de5eda6ab044c96723efa45ac438b446c4fc588d33874dec21","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AF-C07","legacy_id":204,"coberturas":[{"legacy_id":204,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Cobertura conjunta de CLIENT_HOME y CLIENT_PAYMENTS mediante gemelos de condición y contrato fuente idénticos."}],"paquete":{"tipo":"NUEVA","codigo":"S22AF-C07","clave":"s22af_legacy_204_payments","familia":"UI_MESSAGES","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Estados del countdown de vencimiento","descripcion":"BLOQUEAR incumplimiento: El countdown de vencimiento tiene 3 estados visuales según tiempo restante: (1) normal (>24h): texto verde, sin urgencia. (2) alerta (6h-24h): texto naranja, icono de reloj animado. (3) crítico (<6h): texto rojo, fondo rojo muy suave, pulso sutil. Referencias literales del contrato fuente: {\"estados\":{\"alerta\":{\"color\":\"naranja\",\"icono\":\"reloj_animado\",\"umbral\":\"6h-24h\"},\"normal\":{\"color\":\"verde\",\"umbral\":\">24h\"},\"critico\":{\"color\":\"rojo\",\"fondo\":\"rojo_suave\",\"umbral\":\"<6h\",\"animacion\":\"pulso\"}}}. Umbrales: public.lf_global_config CLIENT.COUNTDOWN_NORMAL_HOURS y CLIENT.COUNTDOWN_CRITICAL_HOURS. Binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/204","solicitante":"Cristhian / Claude S22-AF"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"af_countdown"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"y","izq":{"op":">","izq":{"hecho":"af_hours_normal"},"der":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS"}},"der":{"op":"=","izq":{"hecho":"af_normal_bad"},"der":{"lit":true}}},"der":{"op":"y","izq":{"op":"y","izq":{"op":">=","izq":{"hecho":"af_hours_critical"},"der":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS"}},"der":{"op":"<=","izq":{"hecho":"af_hours_normal"},"der":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS"}}},"der":{"op":"=","izq":{"hecho":"af_alert_bad"},"der":{"lit":true}}}},"der":{"op":"y","izq":{"op":"<","izq":{"hecho":"af_hours_critical"},"der":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS"}},"der":{"op":"=","izq":{"hecho":"af_critical_bad"},"der":{"lit":true}}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":true,"af_alert_bad":false,"af_critical_bad":false,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":1},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":19}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":false,"af_alert_bad":true,"af_critical_bad":false,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":0},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":18}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":false,"af_alert_bad":true,"af_critical_bad":false,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":-18},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":0}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":false,"af_alert_bad":false,"af_critical_bad":true,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":-19},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":-1}},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"af_countdown":true,"af_normal_bad":true,"af_alert_bad":false,"af_critical_bad":true,"af_hours_normal":{"param":"CLIENT.COUNTDOWN_NORMAL_HOURS","mas":0},"af_hours_critical":{"param":"CLIENT.COUNTDOWN_CRITICAL_HOURS","mas":18}},"esperado":false}]},"relacionadas":["S22AF-C04"],"hash_paquete":"84a6b8214e7546381b5eccb153e2cd813e0e507a3115a3d1f26e213ab1db87e8","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-25 22:58 Lima: Revisado: literales, gemelos CLIENT_HOME/PAYMENTS, parámetros y clase/alcance conformes');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22AF_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22AF_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22AF_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22AF_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22AF_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 22:58 Lima'),h,'GPT / Claude S22-AF independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22AF_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22AF_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22AF_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22AF_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $af$;
COMMIT;
